import pandas as pd

def clean(df):
    df = df[(df['flipper_length_mm'] >= 170) & (df['flipper_length_mm'] <= 235) & pd.notna(df['flipper_length_mm'])]
    allowed_species = ['Adelie', 'Chinstrap', 'Gentoo']
    df = df[df['species'].isin(allowed_species)]
    df['sex'] = df['sex'].replace({'FEMALE': 'female'})
    return df

def answer(df):
    grouped = df.groupby('species')['flipper_length_mm'].mean()
    return {species: avg for species, avg in grouped.items() if avg is not None}
